from collections import defaultdict, deque
h,w=len(grid),len(grid[0])
def comps_by_color(g):
 h,w=len(g),len(g[0]); vis=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if (r,c) in vis: continue
   q=[(r,c)]; vis.add((r,c)); pts=[]
   while q:
    a,b=q.pop(); pts.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<h and 0<=y<w and (x,y) not in vis and g[x][y]==col:
      vis.add((x,y)); q.append((x,y))
   out.append((col,pts))
 return out
